1: // the compile functions which compile a Node into JavaScript are not
2: // exposed as class methods for security reasons to prevent being able to
3: // override them or create fake Nodes. Instead, only compile functions of
4: // registered nodes can be executed
5: 
6: function factory () {
7:   // map with node type as key and compile functions as value
8:   var compileFunctions = {}
9: 
10:   /**
11:    * Register a compile function for a node
12:    * @param {string} type
13:    * @param {function} compileFunction
14:    *                      The compile function, invoked as
15:    *                      compileFunction(node, defs, args)
16:    */
17:   function register(type, compileFunction) {
18:     if (compileFunctions[type] === undefined) {
19:       compileFunctions[type] = compileFunction;
20:     }
21:     else {
22:       throw new Error('Cannot register type "' + type + '": already exists');
23:     }
24:   }
25: 
26:   /**
27:    * Compile a Node into JavaScript
28:    * @param {Node} node
29:    * @param {Object} defs     Object which can be used to define functions
30:    *                          or constants globally available for the compiled
31:    *                          expression
32:    * @param {Object} args     Object with local function arguments, the key is
33:    *                          the name of the argument, and the value is `true`.
34:    *                          The object may not be mutated, but must be
35:    *                          extended instead.
36:    * @return {string} Returns JavaScript code
37:    */
38:   function compile (node, defs, args) {
39:     if (Object.hasOwnProperty.call(compileFunctions, node.type)) {
40:       var compileFunction = compileFunctions[node.type];
41:       return compileFunction(node, defs, args);
42:     }
43:     else if (typeof node._compile === 'function' &&
44:         !Object.hasOwnProperty.call(node, '_compile')) {
45:       // Compatibility for CustomNodes
46:       // TODO: this is a security risk, change it such that you have to register CustomNodes separately in math.js, like math.expression.node.register(MyCustomNode)
47:       return node._compile(defs, args);
48:     }
49:     else {
50:       throw new Error('Cannot compile node: unknown type "' + node.type + '"');
51:     }
52:   }
53: 
54:   return {
55:     register: register,
56:     compile: compile
